```csharp
// GameManager.cs
public class GameManager : MonoBehaviour
{
    public static GameManager instance;
    public bool isGameOver = false;
    public int score = 0;

    void Awake()
    {
        instance = this;
    }

    void Update()
    {
        if (!isGameOver)
        {
            // Update score and check for collisions
            UpdateScore();
            CheckCollisions();
        }
    }

    void UpdateScore()
    {
        // Increment score when the player passes through a pipe
        score += 1;
    }

    void CheckCollisions()
    {
        // Check for collisions with pipes or ground
        if (CollisionWithPipe() || CollisionWithGround())
        {
            EndGame();
        }
    }

    void EndGame()
    {
        isGameOver = true;
        // Display game over message and reset game
    }
}
```

