#include <iostream>
using namespace std;

// Base class with private, protected, and public members
class Base {
public:
    // Public member
    int publicVar;

    // Public member function
    void publicFunc() {
        cout << "Base publicFunc called" << endl;
    }

protected:
    // Protected member
    int protectedVar;

    // Protected member function
    void protectedFunc() {
        cout << "Base protectedFunc called" << endl;
    }

private:
    // Private member
    int privateVar;

    // Private member function
    void privateFunc() {
        cout << "Base privateFunc called" << endl;
    }

    // Virtual function for polymorphism
    virtual void display() {
        cout << "Base display called" << endl;
    }
};

// Derived class 1
class Derived1 : public Base {
public:
    // Overloaded function
    void display() {
        cout << "Derived1 display called" << endl;
    }

    // Overloaded function with different parameters
    void display(int x) {
        cout << "Derived1 display with parameter: " << x << endl;
    }
};

// Derived class 2
class Derived2 : public Base {
public:
    // Overloaded function
    void display() {
        cout << "Derived2 display called" << endl;
    }

    // Overloaded function with different parameters
    void display(int x) {
        cout << "Derived2 display with parameter: " << x << endl;
    }
};

// Composite class
class Composite {
public:
    Base* base;

    Composite() {
        base = new Base();
        cout << "Composite constructor called" << endl;
    }

    ~Composite() {
        delete base;
        cout << "Composite destructor called" << endl;
    }

    void show() {
        base->display();
    }
};

// Aggregated class
class Aggregated {
public:
    Derived1 derived1;

    Aggregated() {
        cout << "Aggregated constructor called" << endl;
    }

    ~Aggregated() {
        cout << "Aggregated destructor called" << endl;
    }

    void show() {
        derived1.display();
    }
};

// Virtual base class
class VirtualBase {
public:
    virtual void show() {
        cout << "VirtualBase show called" << endl;
    }
};

// Derived class with virtual inheritance
class DerivedFromVirtual : virtual public VirtualBase {
public:
    void show() override {
        cout << "DerivedFromVirtual show called" << endl;
    }
};

// Derived class with multiple inheritance
class MultiDerived : public Derived1, public DerivedFromVirtual {
public:
    void show() override {
        cout << "MultiDerived show called" << endl;
    }
};

// Main function to demonstrate usage
int main() {
    // Example of polymorphism
    Base* basePtr = new Derived1();
    basePtr->display();
    basePtr->display(10);
    delete basePtr;

    // Example of composition
    Composite composite;
    composite.show();

    // Example of aggregation
    Aggregated aggregated;
    aggregated.show();

    // Example of multiple inheritance
    MultiDerived multiDerived;
    multiDerived.show();

    // Example of virtual inheritance
    VirtualBase* virtualBasePtr = new DerivedFromVirtual();
    virtualBasePtr->show();
    delete virtualBasePtr;

    return 0;
}

