using System;
using System.Collections.Generic;
using System.Data;

// Interface for the database record iterator
public interface IDatabaseRecordIterator
{
    bool MoveNext();
    DatabaseRecord Current { get; }
    void Reset();
}

// Represents a single database record
public class DatabaseRecord
{
    public int Id { get; set; }
    public string Name { get; set; }
    public string Value { get; set; }
}

// Concrete iterator class that implements the IDatabaseRecordIterator interface
public class DatabaseRecordIterator : IDatabaseRecordIterator
{
    private List<DatabaseRecord> records;
    private int currentIndex = -1;

    public DatabaseRecordIterator(List<DatabaseRecord> records)
    {
        this.records = records;
    }

    public bool MoveNext()
    {
        currentIndex++;
        return currentIndex < records.Count;
    }

    public DatabaseRecord Current
    {
        get
        {
            if (currentIndex < 0 || currentIndex >= records.Count)
            {
                throw new InvalidOperationException("Invalid current index.");
            }
            return records[currentIndex];
        }
    }

    public void Reset()
    {
        currentIndex = -1;
    }
}

// Class that provides the database records and acts as the 'collection'
public class DatabaseRecordCollection
{
    private List<DatabaseRecord> records;

    public DatabaseRecordCollection()
    {
        // Simulate fetching records from a database
        records = new List<DatabaseRecord>
        {
            new DatabaseRecord { Id = 1, Name = "Record 1", Value = "Value 1" },
            new DatabaseRecord { Id = 2, Name = "Record 2", Value = "Value 2" },
            new DatabaseRecord { Id = 3, Name = "Record 3", Value = "Value 3" }
        };
    }

    // Method to get the iterator
    public IDatabaseRecordIterator GetIterator()
    {
        return new DatabaseRecordIterator(records);
    }
}

// Example usage
class Program
{
    static void Main(string[] args)
    {
        // Create a database record collection
        DatabaseRecordCollection recordCollection = new DatabaseRecordCollection();

        // Get the iterator
        IDatabaseRecordIterator iterator = recordCollection.GetIterator();

        // Traverse the records
        while (iterator.MoveNext())
        {
            DatabaseRecord currentRecord = iterator.Current;
            Console.WriteLine("ID: {0}, Name: {1}, Value: {2}", currentRecord.Id, currentRecord.Name, currentRecord.Value);
        }
    }
}

